options.afterRender:
(function(){
  var root = (typeof context !== 'undefined' && context.element) ? context.element : (typeof element !== 'undefined' ? element : document);
  var el = root.querySelector ? root.querySelector('#fs-clock') : null;
  if (!el) return;
  function tick(){ var d=new Date(); el.textContent = d.toLocaleTimeString('pt-BR',{hour12:false}) + ' BRT'; }
  tick(); if (el._t) clearInterval(el._t); el._t = setInterval(tick, 1000);
})();

options.styles:
:root{--fs-accent:#00c8ff;--fs-alert:#ff5a5a;--fs-text:#eef4f8;--fs-dim:#8fa3b3;--fs-line:rgba(255,255,255,.08);
--fs-mono:ui-monospace,"JetBrains Mono",Menlo,Consolas,monospace;}
.fs-banner{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;font-family:var(--fs-mono);color:var(--fs-dim);padding:6px 4px 10px;border-bottom:1px solid var(--fs-line);}
.fs-banner-left{display:flex;align-items:center;gap:12px;font-size:12px;letter-spacing:.04em;}
.fs-banner-right{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.fs-prompt{color:var(--fs-accent);}.fs-path{color:var(--fs-text);margin-left:6px;}.fs-sep{opacity:.35;}
.fs-title{color:var(--fs-text);font-weight:700;letter-spacing:.14em;font-size:13px;}.fs-thin{font-weight:400;color:var(--fs-dim);}
.fs-pill{display:inline-flex;align-items:center;gap:8px;padding:5px 12px;border:1px solid rgba(255,255,255,.16);border-radius:999px;color:var(--fs-text);font-family:var(--fs-mono);font-size:11px;letter-spacing:.12em;text-decoration:none;background:rgba(8,12,18,.6);}
.fs-pill--ok{border-color:rgba(0,200,255,.35);background:rgba(0,200,255,.12);}
.fs-pill--alert{border-color:rgba(255,90,90,.45);background:rgba(255,90,90,.12);color:#ffd5d5;}
.fs-pill--alert:hover{background:rgba(255,90,90,.25);}
.fs-dot{width:7px;height:7px;border-radius:50%;background:var(--fs-accent);animation:fs-pulse 1.8s ease-out infinite;}
@keyframes fs-pulse{0%{box-shadow:0 0 0 0 rgba(0,200,255,.55)}100%{box-shadow:0 0 0 9px rgba(0,200,255,0)}}
.fs-ticker{overflow:hidden;white-space:nowrap;margin-top:8px;font-family:var(--fs-mono);font-size:11px;letter-spacing:.16em;color:var(--fs-dim);}
.fs-ticker-track{display:inline-block;animation:fs-scroll 40s linear infinite;}
.fs-ticker-track span{margin-right:42px;}.fs-ticker-track span::first-letter{color:var(--fs-accent);}
@keyframes fs-scroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}

options.getOption:
// Business Charts — tráfego limpo x ataque (DEMO com random walk; trocar query por dado real)
const ctx = (typeof context !== 'undefined') ? context : null;
const frames = ctx ? ctx.panel.data.series : data.series;
const vals = (f) => (f && f.values) ? (f.values.toArray ? f.values.toArray() : Array.from(f.values)) : [];
const pick = (i) => {
  const fr = frames[i]; if (!fr) return { t: [], v: [] };
  const tf = fr.fields.find(x => x.type === 'time'); const vf = fr.fields.find(x => x.type === 'number');
  return { t: vals(tf), v: vals(vf) };
};
const a = pick(0), b = pick(1);
const clean  = a.v.map(v => Math.round(820 + v * 55));
const attack = b.v.map(v => Math.max(0, Math.round(140 + v * 45)));
const times  = a.t.map(t => new Date(t).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }));
const mono = 'ui-monospace, JetBrains Mono, Menlo, Consolas, monospace';
return {
  backgroundColor: 'transparent',
  animationDuration: 900, animationEasing: 'cubicOut',
  textStyle: { fontFamily: mono },
  legend: { top: 4, right: 8, textStyle: { color: '#8fa3b3', fontSize: 11, fontFamily: mono }, itemWidth: 14, itemHeight: 3, icon: 'rect' },
  tooltip: { trigger: 'axis', backgroundColor: 'rgba(8,12,18,.95)', borderColor: 'rgba(0,200,255,.35)', textStyle: { color: '#eef4f8', fontFamily: mono, fontSize: 11 }, valueFormatter: v => v + ' Mbps' },
  grid: { left: 44, right: 14, top: 34, bottom: 26 },
  xAxis: { type: 'category', data: times, boundaryGap: false, axisLine: { lineStyle: { color: 'rgba(255,255,255,.12)' } }, axisLabel: { color: '#8fa3b3', fontSize: 10 }, axisTick: { show: false } },
  yAxis: { type: 'value', splitLine: { lineStyle: { color: 'rgba(255,255,255,.06)' } }, axisLabel: { color: '#8fa3b3', fontSize: 10, formatter: '{value}' } },
  series: [
    { name: 'TRÁFEGO LIMPO', type: 'line', data: clean, smooth: true, showSymbol: false,
      lineStyle: { width: 2, color: '#00c8ff', shadowColor: 'rgba(0,200,255,.6)', shadowBlur: 12 },
      areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [{ offset: 0, color: 'rgba(0,200,255,.35)' }, { offset: 1, color: 'rgba(0,200,255,0)' }] } } },
    { name: 'ATAQUE MITIGADO', type: 'line', data: attack, smooth: true, showSymbol: false,
      lineStyle: { width: 2, color: '#ff5a5a', shadowColor: 'rgba(255,90,90,.6)', shadowBlur: 12 },
      areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [{ offset: 0, color: 'rgba(255,90,90,.35)' }, { offset: 1, color: 'rgba(255,90,90,0)' }] } } }
  ]
};
